code='''def transform(grid):
    """Compress each 3x3 block to its most common non-background color."""
    h, w = len(grid), len(grid[0])
    out = [[0 for _ in range(w // 3)] for _ in range(h // 3)]
    for br in range(h // 3):
        for bc in range(w // 3):
            counts = {}
            for r in range(br * 3, br * 3 + 3):
                for c in range(bc * 3, bc * 3 + 3):
                    v = grid[r][c]
                    if v != 5:
                        counts[v] = counts.get(v, 0) + 1
            if counts:
                out[br][bc] = max(counts, key=counts.get)
    return out
'''
